 public function assertCurrent(array$input,string$code,bool$checkWorkforce):void{$canonicalObjects=[];foreach($input['objects']??[]as$o){$selected=array_filter($o['entitlements']??[],static fn($r)=>preg_match('/^case-\d+-item-\d+$/D',(string)($r['sourceId']??''))===1||str_starts_with((string)($r['sourceId']??''),'completion-'));if($selected)$canonicalObjects[(int)$o['objectId']]=true;}if(!$canonicalObjects)return;$current=[];foreach($this->facts((string)$input['reportDate'])as$f)$current[(int)$f['id']]=$this->canonical($f,(string)$input['reportDate']);foreach($input['objects']??[]as$o){if(!isset($canonicalObjects[(int)$o['objectId']]))continue;$now=$current[(int)$o['objectId']]??null;if(!$now)throw new \DomainException($code);foreach(['fundCents','plannedPremiumCents','shaftBp','kssBp']as$field)if(array_key_exists($field,$o)&&($o[$field]??null)!==($now[$field]??null))throw new \DomainException($code);$rights=[];foreach($now['entitlements']as$r)$rights[$r['rightKey']]=$r;foreach($o['entitlements']??[]as$r){$key=implode('|',[(int)$o['objectId'],$r['sourceKind'],$r['sourceId'],$r['kind']]);$fresh=$rights[$key]??null;if(!$fresh||!hash_equals((string)$r['sourceRevision'],(string)$fresh['sourceRevision'])||(int)$r['grossCents']!==(int)$fresh['cumulativeGrossCents'])throw new \DomainException($code);}if($checkWorkforce)foreach($o['recipients']??[]as$r){$identity=$this->identity((string)$r['employeeId']);if(($r['employment']??'unknown')!==$identity['employment']||($r['employmentAsOf']??null)!==$identity['asOf'])throw new \DomainException($code);}}}
